import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"نظرية الأبعاد وتصنيفها","description":"","frontmatter":{},"headers":[],"relativePath":"ar/80-位面理论与分类.md","filePath":"ar/80-位面理论与分类.md","lastUpdated":1789183869000}'),l={name:"ar/80-位面理论与分类.md"};function o(h,t,i,n,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="نظرية-الأبعاد-وتصنيفها" tabindex="-1">نظرية الأبعاد وتصنيفها <a class="header-anchor" href="#نظرية-الأبعاد-وتصنيفها" aria-label="Permalink to &quot;نظرية الأبعاد وتصنيفها&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>80</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>نظرية الأبعاد، تصنيف الأبعاد، حواجز القوانين، إحداثيات الأبعاد، كون هنغ يوان</td></tr></tbody></table><h2 id="أولاً-التعريف-الأساسي-للأبعاد" tabindex="-1">أولاً: التعريف الأساسي للأبعاد <a class="header-anchor" href="#أولاً-التعريف-الأساسي-للأبعاد" aria-label="Permalink to &quot;أولاً: التعريف الأساسي للأبعاد&quot;">​</a></h2><p>في إطار كون وانلينغ هنغماو الأصلاني (كون هنغ يوان)، يشير «البُعد» إلى منطقة وجود تحدّدها مجموعة مستقرة نسبياً من القوانين، وتمتلك استمرارية مستقلة للزمان والمكان. البُعد ليس مجرد «عالم آخر»، بل إسقاط متجسّد لشبكة القوانين في فترات مختلفة من المتغيرات. لكل بُعد ثوابته الفيزيائية الفريدة، وكثافة طاقته، وسرعة زمنه، ومستوى نشاط وعيه، وهذه المتغيرات معاً تشكل «بصمة القوانين» لهذا البُعد.</p><p>ينبع وجود الأبعاد من عدم انتظام شبكة القوانين في كون هنغ يوان. فخلال تشغيل القوانين الأصلانية للكون، وبسبب الاختلافات في توزيع الطاقة واضطراب الوعي والتطور التاريخي، تشكّلت طبيعياً مناطق قوانين لا حصر لها بمتغيرات مختلفة. وهذه المناطق تفصلها «حواجز القوانين»، التي تعتمد قوتها على درجة الاختلاف في متغيرات القوانين بين الأبعاد المتجاورة — فكلما زاد الاختلاف، زادت سماكة الحاجز، وارتفعت صعوبة العبور.</p><p>تحتل آلية المرساة مكانة جوهرية في نظرية الأبعاد. فالمرساة في جوهرها عقدة مستقرة في شبكة القوانين؛ فهي لا تحافظ على استقرار قوانين بُعدها فحسب، بل يمكنها أيضاً أن تكون المعيار المرجعي للاتصالات عبر الأبعاد. فكل سلوك تفاعلي من عبور وتواصل وعلم آثار عبر الأبعاد، يجب أن يتخذ المرساة نقطة أصل للإحداثيات للتحديد والمعايرة.</p><h2 id="ثانياً-نظام-تصنيف-الأبعاد" tabindex="-1">ثانياً: نظام تصنيف الأبعاد <a class="header-anchor" href="#ثانياً-نظام-تصنيف-الأبعاد" aria-label="Permalink to &quot;ثانياً: نظام تصنيف الأبعاد&quot;">​</a></h2><p>تُقسَّم أبعاد كون هنغ يوان، وفقاً لمتغيرات القوانين ومستويات الطاقة ودرجة تطور الحضارة، إلى الفئات الخمس الكبرى التالية:</p><table tabindex="0"><thead><tr><th>الفئة</th><th>خصائص القوانين</th><th>كثافة الطاقة</th><th>الصورة الحضارية النموذجية</th><th>صعوبة العبور</th></tr></thead><tbody><tr><td>بُعد هيمنة المادة</td><td>القوانين الفيزيائية مهيمنة، الطاقة كامنة</td><td>منخفضة</td><td>الحضارة التكنولوجية، حضارة الزراعة المبتدئة</td><td>منخفضة</td></tr><tr><td>بُعد الطاقة المتجلية</td><td>قوانين الطاقة شبه ظاهرة، أنظمة الزراعة ناضجة</td><td>متوسطة</td><td>حضارة الزراعة المتوسطة والعليا، الحضارة السحرية</td><td>متوسطة</td></tr><tr><td>بُعد هيمنة الوعي</td><td>قوانين الوعي ظاهرة، المادة قابلة للتشكيل بالإرادة</td><td>عالية</td><td>حضارة الأجساد الروحية، حضارة تجميع الوعي</td><td>عالية</td></tr><tr><td>بُعد القوانين المفتتة</td><td>القوانين غير مستقرة، شقوق قوانين كثيرة</td><td>عالية جداً وفوضوية</td><td>الأبعاد الوحشية، أبعاد الآثار</td><td>عالية جداً</td></tr><tr><td>البُعد القريب من الأصل</td><td>قريب من القوانين الأصلانية للكون، المتغيرات تقترب من الحدود</td><td>يقترب من الأصل</td><td>الحضارة العليا، حراس الأبعاد</td><td>الحد النظري</td></tr></tbody></table><p>إلى جانب الفئات الخمس الكبرى المذكورة، توجد أيضاً أنواع خاصة من الأبعاد، منها: البُعد المرآتي (وجود موازٍ شديد التناظر في متغيرات القوانين مع بُعد معين)، والبُعد الوسيط (منطقة انتقالية تقع بين حواجز قوانين بُعدين رئيسيين)، والبُعد الخامل (بُعد قديم شديد الانخفاض في نشاط القوانين، شبه متوقف)، والبُعد الوليد (بُعد شاب تشكّل حديثاً في شبكة القوانين، متغيراته لم تستقر بعد).</p><h2 id="ثالثاً-إحداثيات-الأبعاد-ومبدأ-التحديد" tabindex="-1">ثالثاً: إحداثيات الأبعاد ومبدأ التحديد <a class="header-anchor" href="#ثالثاً-إحداثيات-الأبعاد-ومبدأ-التحديد" aria-label="Permalink to &quot;ثالثاً: إحداثيات الأبعاد ومبدأ التحديد&quot;">​</a></h2><p>شرط التفاعل عبر الأبعاد هو تحديد دقيق للأبعاد. أنشأ كون هنغ يوان «نظام إحداثيات الأبعاد رباعي الأبعاد» قائماً على المرساة، يتحدد فيه كل بُعد بشكل فريد بأربعة متغيرات:</p><ol><li><strong>رمز بصمة القوانين</strong>: معرّف فريد يُولَّد بتحويل متغيرات القوانين الجوهرية للبُعد عبر التجزئة، طوله 128 بتاً.</li><li><strong>درجة الارتباط بالمرساة</strong>: قوة الاتصال بين البُعد وشبكة المراسي المعروفة، تتراوح من 0 إلى 1.</li><li><strong>نسبة سرعة الزمن</strong>: نسبة سرعة زمن البُعد إلى الزمن القياسي لكون هنغ يوان، ويتراوح المدى الشائع من 0.1 إلى 10.</li><li><strong>عدد الأبعاد المكانية</strong>: عدد الأبعاد المكانية المدركة للبُعد، وعادة من 3 إلى 11 بُعداً.</li></ol><p>تشمل طرق الحصول على إحداثيات الأبعاد: الكشف التلقائي بشبكة المرساة، واستعادة إشارات التواصل عبر الأبعاد، وبقايا الإحداثيات في الآثار الأثرية، والتسجيل اليدوي من عبّار الأبعاد. جميع إحداثيات الأبعاد المؤكدة تُدخل في «المستودع المركزي لإحداثيات الأبعاد لكون هنغ يوان»، وتتولاها صيانة موحدة من إدارة الأبعاد التابعة للمجلس التشريعي للمرساة.</p><h2 id="رابعاً-التفاعلات-الطبيعية-بين-الأبعاد" tabindex="-1">رابعاً: التفاعلات الطبيعية بين الأبعاد <a class="header-anchor" href="#رابعاً-التفاعلات-الطبيعية-بين-الأبعاد" aria-label="Permalink to &quot;رابعاً: التفاعلات الطبيعية بين الأبعاد&quot;">​</a></h2><p>حتى دون عبور نشط، توجد ظواهر تفاعل طبيعي بين الأبعاد. أكثرها شيوعاً «تسرب القوانين» — إذ بسبب ضعف موضعي في الحواجز بين الأبعاد المتجاورة، يتسلل عدد قليل من متغيرات القوانين بعضها إلى بعض، مما يسبب ظواهر شاذة محلية. فمثلاً «الأحداث الخارقة للطبيعة» التي تظهر أحياناً في أبعاد هيمنة المادة، غالباً ما تكون ناجمة عن تسرب قوانين من بُعد الطاقة المتجلية المجاور.</p><p>وشكل آخر من التفاعل الطبيعي هو «رنين الأبعاد». فعندما تتشابه رموز بصمة القوانين لبُعدين بدرجة عالية، ينشأ بينهما رنين قوانين دوري، يتجلى في ظهور أحداث تاريخية متشابهة، ومسارات حضارية متشابهة، وحتى أقدار شخصية متشابهة في البُعدين خلال فترات زمنية محددة. ورنين الأبعاد موضوع بحث مهم في علم آثار الأبعاد؛ فبتحليل أنماط الرنين يمكن استنتاج الحالة الحضارية لأبعاد مجهولة.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>نظرية الأبعاد هي حجر الأساس النظري لكل ممارسات التفاعل عبر الأبعاد. الفهم الدقيق لجوهر الأبعاد وتصنيفها ومبادئ تحديدها هو شرط وضع قواعد العبور والمعايير الأخلاقية وآليات الوقاية والضبط. يلتزم استكشاف الأبعاد في كون هنغ يوان دائماً بمبدأ «الإدراك أولاً، والتفاعل بحذر»، بما يضمن أنه أثناء توسيع حدود الحضارة، لا يحدث أي تدخل لا رجعة فيه في التطور الذاتي لأي بُعد.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>81-位面穿梭规则 (قواعد العبور بين الأبعاد)</li><li>88-跨位面伦理准则 (المعايير الأخلاقية عبر الأبعاد)</li><li>28-跨位面锚点连接 (اتصالات المرساة عبر الأبعاد)</li></ul>',21)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
